use crate::writer::CodeWriter;

use super::client_emitter::{emit_cpp_enum, emit_cpp_module, emit_cpp_struct, emit_cpp_view};
use super::*;

pub(super) fn emit_cpp20_spec(spec: &HybridFileSpec, abi_header: &str) -> String {
    let mut out = CodeWriter::with_capacity(16 * 1024);
    writeln!(
        out,
        "// @generated by nve-codegen (hybrid C++20 Spec & Client) — DO NOT EDIT."
    );
    writeln!(out, "#pragma once");
    writeln!(out);
    writeln!(out, "#include <array>");
    writeln!(out, "#include <cstddef>");
    writeln!(out, "#include <cstdint>");
    writeln!(out, "#include <cstring>");
    writeln!(out, "#include <optional>");
    writeln!(out, "#include <span>");
    writeln!(out, "#include <stdexcept>");
    writeln!(out, "#include <string>");
    writeln!(out, "#include <string_view>");
    writeln!(out, "#include <utility>");
    writeln!(out, "#include <vector>");
    writeln!(out, "#include \"{abi_header}\"");
    writeln!(out, "#include <nve/host/bin_codec.hpp>");
    writeln!(out, "#include <nve/host/hybrid_runtime.hpp>");
    writeln!(out);
    writeln!(out, "namespace nve::hybrid {{");
    writeln!(out);

    emit_cpp_bin_codec(&mut out);

    for e in &spec.enums {
        emit_cpp_enum(&mut out, e);
    }

    for s in spec.structs_topological() {
        emit_cpp_struct(&mut out, s, spec);
    }

    for m in &spec.modules {
        emit_cpp_module(&mut out, m, spec);
    }

    for v in &spec.views {
        emit_cpp_view(&mut out, v, spec);
    }

    writeln!(out, "}} // namespace nve::hybrid");
    out.into_string()
}

pub(super) fn emit_cpp_bin_codec(out: &mut CodeWriter) {
    // The `NveBinValue` codec and `DynamicValue` are the static `nve::host_cxx` runtime
    // (`packages/core/host-cxx`); only the bridge to this file's C slices is generated.
    writeln!(out, "#ifndef NVE_HYBRID_CPP_COMMON_DEFINED");
    writeln!(out, "#define NVE_HYBRID_CPP_COMMON_DEFINED 1");
    writeln!(out, "using nve::host::BinReader;");
    writeln!(out, "using nve::host::BinWriter;");
    writeln!(out, "using nve::host::DynamicValue;");
    writeln!(out);
    writeln!(
        out,
        "/// `w`'s encoded bytes; throws when an earlier write failed (invalid UTF-8, over-long value,"
    );
    writeln!(
        out,
        "/// bad container mark), so a partial encoding never crosses the ABI."
    );
    writeln!(
        out,
        "inline std::span<const uint8_t> checked_bytes(const BinWriter& w) {{"
    );
    writeln!(
        out,
        "  if (!w.ok()) throw std::runtime_error(\"NveBinValue encoding failed\");"
    );
    writeln!(out, "  return w.bytes();");
    writeln!(out, "}}");
    writeln!(out);
    writeln!(out, "/// [`checked_bytes`] as a C slice.");
    writeln!(out, "inline NveBufferSlice to_slice(const BinWriter& w) {{");
    writeln!(out, "  const auto bytes = checked_bytes(w);");
    writeln!(
        out,
        "  return NveBufferSlice{{bytes.data(), bytes.size()}};"
    );
    writeln!(out, "}}");
    writeln!(out);
    writeln!(
        out,
        "/// Throws when decoding hit malformed or truncated `NveBinValue` bytes."
    );
    writeln!(out, "inline void require_ok(const BinReader& r) {{");
    writeln!(
        out,
        "  if (!r.ok()) throw std::runtime_error(\"malformed NveBinValue\");"
    );
    writeln!(out, "}}");
    writeln!(out, "#endif // NVE_HYBRID_CPP_COMMON_DEFINED");
}
